import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> [side, price, qty, seq]
    trades = []
    seq_counter = 0

    def add_resting(side, id, price, qty, seq):
        book[id] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id))
        else:
            heapq.heappush(sell_heap, (price, seq, id))

    def clean_buy():
        while buy_heap:
            negp, seq, id = buy_heap[0]
            if id not in book or book[id][2] <= 0 or book[id][3] != seq:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, seq, id = sell_heap[0]
            if id not in book or book[id][2] <= 0 or book[id][3] != seq:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            id = order[1]
            if id in book and book[id][2] > 0:
                del book[id]
            continue

        if typ == 'limit':
            _, id, side, price, qty = order
        elif typ == 'ioc':
            _, id, side, price, qty = order
        elif typ == 'market':
            _, id, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                p, s_seq, s_id = sell_heap[0]
                if typ != 'market' and p > price:
                    break
                sell_order = book[s_id]
                trade_qty = min(remaining, sell_order[2])
                trades.append([id, s_id, p, trade_qty])
                remaining -= trade_qty
                sell_order[2] -= trade_qty
                if sell_order[2] == 0:
                    del book[s_id]
                    heapq.heappop(sell_heap)
            if remaining > 0 and typ == 'limit':
                seq_counter += 1
                add_resting('buy', id, price, remaining, seq_counter)

        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, b_seq, b_id = buy_heap[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                buy_order = book[b_id]
                trade_qty = min(remaining, buy_order[2])
                trades.append([b_id, id, p, trade_qty])
                remaining -= trade_qty
                buy_order[2] -= trade_qty
                if buy_order[2] == 0:
                    del book[b_id]
                    heapq.heappop(buy_heap)
            if remaining > 0 and typ == 'limit':
                seq_counter += 1
                add_resting('sell', id, price, remaining, seq_counter)

    return trades

